    function handleMicrosoftSSOLogin(roleKey = 'admin') {
      const screen = document.getElementById('loginLandingScreen');
      window.ramsAuthenticated = true;
      window.ramsUserRole = roleKey;
      try {
        sessionStorage.removeItem('rams_authenticated');
        sessionStorage.removeItem('rams_user_role');
      } catch (e) {}

      if (screen) {
        screen.classList.add('hidden');
      }

      switchRole(roleKey);

      if (roleKey === 'admin' || roleKey === 'a') {
        window._pendingRouteAfterLogin = null;
        if (typeof deselectSchool === 'function') deselectSchool();
        if (typeof deselectProgram === 'function') deselectProgram();
        syncSidebarToCurrentPath(null, null, null);
        renderAdminOverview();
      } else if (window._pendingRouteAfterLogin && window.spaRouter && typeof window.spaRouter.applyRouteState === 'function') {
        const pending = window._pendingRouteAfterLogin;
        window._pendingRouteAfterLogin = null;
        window.spaRouter.applyRouteState(pending);
      } else {
        renderHomepageForRole(roleKey);
      }
    }

    function handleNativeLogin(event) {
      if (event) event.preventDefault();
      const emailInput = document.getElementById('loginEmail') || document.getElementById('loginInputEmail');
      const email = (emailInput?.value || '').trim().toLowerCase();
      const errEl = document.getElementById('loginErrorMsg');

      let roleKey = 'admin';
      if (email.includes('exd') || email.includes('dean') || email.includes('director.eng')) {
        roleKey = 'exd';
      } else if (email.includes('pd') || email.includes('cpe') || email.includes('program')) {
        roleKey = 'pd';
      } else if (email.includes('faculty') || email.includes('prof') || email.includes('teacher')) {
        roleKey = 'faculty';
      } else {
        roleKey = 'admin';
      }

      if (errEl) errEl.classList.add('hidden');
      handleMicrosoftSSOLogin(roleKey);
    }
    window.handleNativeLogin = handleNativeLogin;

    function handleManualEmailLogin(event) {
      handleNativeLogin(event);
    }

